import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Словарь Терминов","description":"","frontmatter":{},"headers":[],"relativePath":"ru/0090-术语词典.md","filePath":"ru/0090-术语词典.md"}'),i={name:"ru/0090-术语词典.md"};function l(o,t,h,n,s,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="словарь-терминов" tabindex="-1">Словарь Терминов <a class="header-anchor" href="#словарь-терминов" aria-label="Permalink to &quot;Словарь Терминов&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>Номер документа</td><td>90</td></tr><tr><td>Модуль</td><td>Приложения и справочные материалы</td></tr><tr><td>Ключевые слова</td><td>словарь терминов, центральные понятия, определения, унифицированная терминология, Вселенная Хэнъюань</td></tr></tbody></table><h2 id="i-пояснения-к-терминологии" tabindex="-1">I. Пояснения к Терминологии <a class="header-anchor" href="#i-пояснения-к-терминологии" aria-label="Permalink to &quot;I. Пояснения к Терминологии&quot;">​</a></h2><p>Настоящий словарь включает центральные термины системы вселенной Симбиотической Цивилизации Якоря, направлен на унификацию использования терминов во всех документах и обеспечение согласованности и точности выражения понятий. Все термины отсортированы по первой букве их китайского пиньиня ; каждая статья содержит название термина, английское справочное название (при наличии), определение и краткое пояснение. Настоящий словарь является динамически обновляемым документом ; по мере расширения системы вселенной в него будут непрерывно добавляться новые термины.</p><h2 id="ii-таблица-центральных-терминов" tabindex="-1">II. Таблица Центральных Терминов <a class="header-anchor" href="#ii-таблица-центральных-терминов" aria-label="Permalink to &quot;II. Таблица Центральных Терминов&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>Термин</th><th>Определение и пояснение</th></tr></thead><tbody><tr><td>1</td><td>Якорь</td><td>Стабильный узел в сети законов, служащий координатным ориентиром для поддержания стабильности законов плоскостей, осуществления межплоскостных соединений и возврата времени. По сути, Якорь — это высокоплотная конденсация исходных законов вселенной в конкретном пространственном месте, обладающая способностью к самоподдержанию и калибровке.</td></tr><tr><td>2</td><td>Симбиотическая Цивилизация Якоря</td><td>Форма цивилизации, основанная на механизме Якоря как технической базе и на симбиотической эволюции как центральной идее. Она выступает против хищнической системы культивации и предлагает вернуть право выбора судьбы и эволюции всем живым существам, реализуя: больше труда — больше выгоды; самостоятельный рост; путь для каждого; совместное продвижение Десяти Тысяч Рас.</td></tr><tr><td>3</td><td>Вселенная Хэнъюань</td><td>Сокращение от «Изначальной Вселенной Ваньлин Хэнмао», вся космическая область, где обитает и управляет Симбиотическая Цивилизация Якоря. Это составное существо, образованное четырьмя уровнями: материальные плоскости, энергетический слой, область сознания и сеть законов.</td></tr><tr><td>4</td><td>Изначальная Вселенная Ваньлин Хэнмао</td><td>Полное название Вселенной Хэнъюань. «Ваньлин» (Десять Тысяч Духов) обозначает все формы жизни, обладающие потенциалом восприятия и эволюции ; «Хэнмао» (Уравновешивающие Якоря) обозначает механизм Якоря, поддерживающий космическое равновесие ; «Изначальная Вселенная» подчёркивает сущностные атрибуты: брать исходные законы за основу и симбиотическую эволюцию за направление.</td></tr><tr><td>5</td><td>Симбиоз</td><td>Одна из центральных идей Симбиотической Цивилизации Якоря, обозначающая совместную эволюцию различных индивидов, рас и цивилизаций через взаимовыгодное сотрудничество, а не хищническую эволюцию за счёт других.</td></tr><tr><td>6</td><td>Хищническая система культивации</td><td>Метод культивации, достигающий самоэволюции путём пожирания энергии, удачи и даже истока слабых. Это тип системы, который Симбиотическая Цивилизация Якоря решительно отвергает, считая его корнем ускорения роста энтропии вселенной и частых разрывов цивилизаций.</td></tr><tr><td>7</td><td>Триста Исходных Систем Культивации</td><td>Ортодоксальные пути культивации, непосредственно извлечённые из исходных законов вселенной и проверенные Якорями, всего триста систем, разделённых на шесть больших категорий: исходное дедуктивное, жизненного цикла, пространственно-правовое, возвышения сознания, симбиотической сети и прикладной инженерии, по пятьдесят систем в каждой категории.</td></tr><tr><td>8</td><td>Три Исходные Основы</td><td>Первые три фундаментальные системы из трёхсот систем — Система Дедуктивной Итерации (№ 1), Система Жизненного Цикла (№ 2) и Система Регулирования Пространственных Правовых Принципов (№ 3) — культивационная основа всех остальных систем.</td></tr><tr><td>9</td><td>Система Дедуктивной Итерации</td><td>Исходная система культивации № 1, характеризующаяся стократным усилением культивационной дедукции, использующая техническое применение Плода Умножения для повышения способности к дедукции в сто раз, подчёркивающая оптимизацию пути культивации через дедукцию, проверку и итерацию.</td></tr><tr><td>10</td><td>Система Жизненного Цикла</td><td>Исходная система культивации № 2, centred на благоприятном цикле жизненной энергии, подчёркивающая, что обмен энергией между культиватором и средой должен быть циклическим, а не хищническим.</td></tr><tr><td>11</td><td>Система Регулирования Пространственных Правовых Принципов</td><td>Исходная система культивации № 3, centred на понимании и регулировании пространственных законов, культивационная основа важных применений, таких как межплоскостное взаимодействие, строительство изолированных пространств и технология Зеркала Репликации.</td></tr><tr><td>12</td><td>Плод Умножения</td><td>Плод Умножения из мира One Piece, технически применённый во Вселенной Хэнъюань, способный повысить способность культиватора к дедукции в сто раз, центральный вспомогательный инструмент Системы Дедуктивной Итерации. Один из стартовых баффов.</td></tr><tr><td>13</td><td>Механизм подряда, связанного с результатом</td><td>Механизм распределения ресурсов Симбиотической Цивилизации Якоря, распределяющий космические культивационные ресурсы индивидам или группам в форме «подряда» ; подрядчики получают право использования ресурсов через труд и вклад, реализуя: больше труда — больше выгоды.</td></tr><tr><td>14</td><td>Стратегия активации 20 %</td><td>Поэтапная стратегическая цель Симбиотической Цивилизации Якоря: на начальном этапе активировать 20 % живых существ вселенной, чтобы они стали Верховными Силачами Плоскостей, используя их как костяк для ведения совместной эволюции остальных 80 % живых существ.</td></tr><tr><td>15</td><td>Верховный Силач Плоскости</td><td>Могучий, достигший чрезвычайно высокого уровня культивации и способный самостоятельно поддерживать стабильность законов плоскости. Это целевая фигура стратегии активации 20 % и важная сила обслуживания сети Якоря.</td></tr><tr><td>16</td><td>Сеть законов</td><td>Четвёртый уровень структуры Вселенной Хэнъюань, операционная основа исходных законов вселенной и корневая основа Якорей. Сеть законов пронизывает всю вселенную и является технической основой всех операций с законами (включая пространственное регулирование, возврат времени и преобразование энергии).</td></tr><tr><td>17</td><td>Плоскость</td><td>Область существования, определяемая относительно стабильным набором законов, обладающая независимой пространственно-временной непрерывностью. Каждая плоскость обладает уникальными физическими постоянными, плотностью энергии, скоростью течения времени и уровнем активности сознания.</td></tr><tr><td>18</td><td>Барьер законов</td><td>Барьер законов, разделяющий соседние плоскости, сила которого зависит от степени различия параметров законов соседних плоскостей. Межплоскостная навигация требует преодоления барьеров законов.</td></tr><tr><td>19</td><td>Отпечаток законов</td><td>Уникальный идентификатор, генерируемый хеш-операцией по центральным параметрам законов каждой плоскости, длиной 128 бит, один из центральных параметров системы координат плоскостей.</td></tr><tr><td>20</td><td>Сначала наблюдение, потом ограниченное вмешательство</td><td>Первейший операционный принцип возврата времени и межплоскостной археологии, требующий, чтобы любой возврат или археология сначала завершили этап чистого наблюдения и, после подтверждения отсутствия серьёзных рисков, проводили лишь ограниченное вмешательство.</td></tr><tr><td>21</td><td>Зеркало Репликации</td><td>Высокоточное устройство репликации, основанное на законах пространственно-правовых принципов, способное выполнить полную репликацию 1:1 целевой области без контакта с оригиналом, центральное оборудование схемы археологии вне места.</td></tr><tr><td>22</td><td>Изолированное пространство</td><td>Независимая область законов, построенная технологией регулирования пространственно-правовых принципов, используемая для размещения археологических копий и в качестве рабочего места археологов, полностью отделённая от внешней вселенной барьерами законов.</td></tr><tr><td>23</td><td>Передача только знаний</td><td>Центральный принцип археологического протокола, означающий, что в процессе археологии от целевого объекта можно получать только абстрактные знания и информацию ; никакие материя, энергия или живые существа не могут быть переданы обратно.</td></tr><tr><td>24</td><td>Очищение информации</td><td>Технический процесс полного удаления отпечатков законов исходной плоскости, содержащихся в сырой информации, с сохранением только чистого семантического содержания, ключевое звено обеспечения безопасности переданных знаний.</td></tr><tr><td>25</td><td>Временной парадокс</td><td>Явление, при котором причинная логика становится самопротиворечивой из-за вмешательства во время операций возврата времени, включающее четыре большие категории: парадокс убийства предка, информационный парадокс, онтологический парадокс и событийный парадокс.</td></tr><tr><td>26</td><td>Причинно-следственная цепь</td><td>Непрерывная линейная структура причин и следствий между событиями, центральное понятие законов времени. Центральный риск операций возврата времени — возмущение причинно-следственной цепи.</td></tr><tr><td>27</td><td>Симбиотическая Конституция</td><td>Основной закон Симбиотической Цивилизации Якоря, обладающий высшей юридической силой, закрепляющий цивилизационную основу борьбы с хищничеством и продвижения симбиоза, а также семь основных конституционных принципов.</td></tr><tr><td>28</td><td>Равенство Десяти Тысяч Рас</td><td>Один из семи основных принципов Симбиотической Конституции, означающий, что все формы жизни, независимо от расы, уровня культивации и происхождения, равны перед законом.</td></tr><tr><td>29</td><td>Аномальная жизнь</td><td>Формы жизни, не соответствующие обычному определению жизни и обладающие особыми формами существования, требующие идентификации и управления по стандартизированным процедурам трёх категорий.</td></tr><tr><td>30</td><td>Аномальная энергия</td><td>Формы энергии, не соответствующие обычной классификации энергии и обладающие особыми атрибутами и моделями поведения, требующие классификации и контроля по стандартизированным процедурам трёх категорий.</td></tr><tr><td>31</td><td>Тёмная замещающая сущность</td><td>Особая форма жизни, затрагивающая этическую проблему сосуществования двух душ, требующая управления по этике двойной души и правилам обработки четырёх ветвей.</td></tr><tr><td>32</td><td>Этика Двойной Души</td><td>Этические принципы для состояния сосуществования двух душ в Тёмной замещающей сущности, ядро которых — уважение прав каждой из двух душ и запрет принудительного слияния или уничтожения одной из сторон.</td></tr><tr><td>33</td><td>Пять Типов Симбиотических Цивилизаций</td><td>Пять типов симбиотических обществ, разделённых по характеристикам цивилизаций реального мира: восточноазиатский интенсивный тип, североевропейский социальный тип, североамериканский плюралистический тип, континентально-европейский социальный тип и развивающийся догоняющий тип.</td></tr><tr><td>34</td><td>Четырёхэтапный Путь Возвышения</td><td>Маршрут из четырёх этапов для общего возвышения Вселенной Хэнъюань: реальная основа → технологическое усиление → эволюция сознания → межзвёздный симбиоз.</td></tr><tr><td>35</td><td>Реальность как основа</td><td>Одна из фундаментальных позиций Симбиотической Цивилизации Якоря, означающая, что реальный мир — единственный настоящий мир, что миры романов — ложные мысленные эксперименты, что вымысел восполняется реальностью, когда её недостаточно, а то, чего нет в реальности, создаётся на основе законов путём возвышения.</td></tr><tr><td>36</td><td>Индекс симбиоза</td><td>Количественный показатель оценки степени интеграции цивилизации или индивида с симбиотической сетью, охватывающий несколько измерений, таких как степень обмена ресурсами, частота сотрудничества и доля альтруистического поведения.</td></tr><tr><td>37</td><td>Собрание Якоря</td><td>Высший орган власти Симбиотической Цивилизации Якоря, состоящий из представителей Десяти Тысяч Рас пропорционально, осуществляющий законодательную власть и право решения важнейших вопросов.</td></tr><tr><td>38</td><td>Симбиотический Исполнительный Комитет</td><td>Высший административный орган Симбиотической Цивилизации Якоря, ответственный за исполнение конституции и законов и повседневное управление.</td></tr><tr><td>39</td><td>Симбиотический Суд</td><td>Высший судебный орган Симбиотической Цивилизации Якоря, независимо осуществляющий судебную власть, ответственный за конституционный контроль и рассмотрение важнейших дел.</td></tr><tr><td>40</td><td>Управление Плоскостей</td><td>Специализированный орган при Собрании Якоря, ответственный за ведение главной базы координат плоскостей, одобрение разрешений на навигацию и управление межплоскостной археологией.</td></tr></tbody></table><h2 id="iii-нормы-использования-терминологии" tabindex="-1">III. Нормы Использования Терминологии <a class="header-anchor" href="#iii-нормы-использования-терминологии" aria-label="Permalink to &quot;III. Нормы Использования Терминологии&quot;">​</a></h2><ol><li>Термины, включённые в настоящий словарь, являются стандартными ; все документы должны отдавать приоритет стандартным формулировкам из настоящего словаря.</li><li>Одно и то же понятие должно использовать один и тот же термин в разных документах ; произвольная замена синонимами не допускается.</li><li>Новые термины, появившиеся в новых вселенных, должны своевременно представляться в Комитет по Терминологии для рассмотрения и добавляться в словарь после одобрения.</li><li>При пересмотре определения термина действует последняя версия настоящего словаря, а содержание пересмотра должно быть зафиксировано в примечаниях к версии документа.</li><li>При цитировании термина при первом появлении может использоваться полное название, в дальнейшем — сокращение, но ясность значения в контексте должна обеспечиваться.</li></ol><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Словарь терминов — языковой краеугольный камень всей системы вселенной. Единая терминологическая система обеспечивает концептуальную согласованность между сотней документов, позволяя читателям без труда переключаться между разными модулями без неоднозначности понимания. По мере обогащения и совершенствования системы вселенной настоящий словарь будет непрерывно обновляться, всегда оставаясь авторитетным источником терминологии для всех документов.</p><h2 id="связанные-документы" tabindex="-1">Связанные Документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные Документы&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Хэн Юаньчжоу: Обзор Вселенной)</li><li>02-锚点本源定义与本质 (Определение и Сущность Истока Якоря)</li><li>99-文档版本与维护说明 (Примечания к версии и обслуживанию документов)</li></ul>',12)])])}const u=d(i,[["render",l]]);export{b as __pageData,u as default};
